import dataclasses
from typing import Any, Dict, List, Optional, Union

@dataclasses.dataclass
class NoSQLRequest:
    """Base class for NoSQL document store request parameters."""
    pass

@dataclasses.dataclass
class NoSQLResponse:
    """Base class for NoSQL document store response objects."""
    success: bool
    message: Optional[str] = None
    data: Optional[Union[Dict[str, Any], List[Dict[str, Any]]]] = None

def normalize_item(item: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalizes a dictionary item for storage or retrieval from a NoSQL document store.
    This function can be extended to handle specific data type conversions,
    attribute renames, or other normalization logic required by the NoSQL service.
    """
    normalized_data = {}
    for key, value in item.items():
        # Example: Convert specific types if necessary
        # if isinstance(value, datetime):
        #     normalized_data[key] = value.isoformat()
        # else:
        normalized_data[key] = value
    return normalized_data

@dataclasses.dataclass
class PutItemRequest(NoSQLRequest):
    """Request to put (create or update) a single item."""
    table_name: str
    item: Dict[str, Any]

@dataclasses.dataclass
class GetItemRequest(NoSQLRequest):
    """Request to get a single item by its primary key."""
    table_name: str
    key: Dict[str, Any]

@dataclasses.dataclass
class DeleteItemRequest(NoSQLRequest):
    """Request to delete a single item by its primary key."""
    table_name: str
    key: Dict[str, Any]

@dataclasses.dataclass
class QueryRequest(NoSQLRequest):
    """Request to query items based on a condition."""
    table_name: str
    key_condition_expression: str
    expression_attribute_values: Dict[str, Any]
    filter_expression: Optional[str] = None

@dataclasses.dataclass
class ItemResponse(NoSQLResponse):
    """Response for operations involving a single item."""
    data: Optional[Dict[str, Any]] = None

@dataclasses.dataclass
class QueryResponse(NoSQLResponse):
    """Response for query operations returning multiple items."""
    data: Optional[List[Dict[str, Any]]] = None

import os
import boto3

class DynamoDBClient:
    def __init__(self, region_name=None, endpoint_url=None):
        if region_name is None:
            region_name = os.environ.get("AWS_REGION", "us-east-1")
        if endpoint_url is None:
            endpoint_url = os.environ.get("DYNAMODB_ENDPOINT_URL")

        self.dynamodb = boto3.resource(
            "dynamodb",
            region_name=region_name,
            endpoint_url=endpoint_url
        )

    def get_table(self, table_name):
        return self.dynamodb.Table(table_name)

    def put_item(self, table_name, item):
        table = self.get_table(table_name)
        response = table.put_item(Item=item)
        return response

    def get_item(self, table_name, key):
        table = self.get_table(table_name)
        response = table.get_item(Key=key)
        return response.get("Item")

    def update_item(self, table_name, key, update_expression, expression_attribute_values):
        table = self.get_table(table_name)
        response = table.update_item(
            Key=key,
            UpdateExpression=update_expression,
            ExpressionAttributeValues=expression_attribute_values,
            ReturnValues="UPDATED_NEW"
        )
        return response

    def delete_item(self, table_name, key):
        table = self.get_table(table_name)
        response = table.delete_item(Key=key)
        return response

from google.cloud import firestore

def conditional_update(document_id, new_value):
    db = firestore.Client()
    doc_ref = db.collection('my-collection').document(document_id)

    @firestore.transactional
    def update_in_transaction(transaction, doc_ref, new_value):
        snapshot = doc_ref.get(transaction=transaction)
        if snapshot.exists:
            current_version = snapshot.get('version')
            updated_data = {
                'value': new_value,
                'version': current_version + 1,
                'updated_by_provider': 'Google Cloud Firestore'
            }
            transaction.update(doc_ref, updated_data)
            print(f"Document {document_id} updated to version {current_version + 1}")
        else:
            initial_data = {
                'value': new_value,
                'version': 1,
                'updated_by_provider': 'Google Cloud Firestore'
            }
            transaction.set(doc_ref, initial_data)
            print(f"Document {document_id} created with version 1")

    transaction = db.transaction()
    update_in_transaction(transaction, doc_ref, new_value)

